import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import ru.wither.skyru.*;
import net.minecraft.network.chat.*;
import net.minecraft.client.multiplayer.chat.*;
import net.minecraft.util.StringDecomposer;

/** Independently reviewed targets + separate observed legacy input. No game/network required. */
public final class TestHubNpcs69 {
    private static int checks;
    private record Anchor(String from,String to,int start,int end){}
    private record Row(String speaker,String source,String target,List<Anchor> anchors){}
    private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
    private static void flag(String key,Object value)throws Exception{var f=SkyRuClient.class.getDeclaredField(key);f.setAccessible(true);f.set(null,value);}
    private static String plain(Component c){var b=new StringBuilder();StringDecomposer.iterateFormatted(c,Style.EMPTY,(i,s,p)->{b.appendCodePoint(p);return true;});return b.toString();}
    private static List<Style> styles(Component c){var r=new ArrayList<Style>();StringDecomposer.iterateFormatted(c,Style.EMPTY,(i,s,p)->{for(int n=0;n<Character.charCount(p);n++)r.add(s);return true;});return r;}
    private static GuiMessage msg(Component c,GuiMessageSource channel){return new GuiMessage(0,c,null,channel,null);}
    private static Component queued(Component c){return SkyRuClient.npcChat(msg(c,GuiMessageSource.SYSTEM_SERVER)).content();}
    private static Style style(int seed,int span){return Style.EMPTY.withColor((seed*0x12305+span*0x30107)&0xffffff).withInsertion("fresh69 "+seed+"/"+span).withClickEvent(new ClickEvent.SuggestCommand("/unchanged-"+seed+"-"+span)).withHoverEvent(new HoverEvent.ShowText(Component.literal("hover69 "+seed+"/"+span)));}
    private static int nth(String text,String term,int occurrence,int start){int at=-1;for(int i=0;i<Math.max(1,occurrence);i++){at=text.indexOf(term,Math.max(start,at+1));check(at>=0,"independent anchor position: "+term);}if(occurrence==0)check(text.indexOf(term,at+1)<0,"anchor unambiguous");return at;}
    private static void add(MutableComponent out,String text,Style s,int mode){if(text.isEmpty())return;if(mode==0)out.append(Component.literal(text).setStyle(s));else for(int i=0;i<text.length();i+=4)out.append(Component.literal(text.substring(i,Math.min(i+4,text.length()))).setStyle(s));}
    private static Component fixture(Row row,String prefix,String suffix,int seed,int mode){var c=Component.empty();int body=row.source().indexOf(": ")+2;add(c,prefix+row.source().substring(0,body),style(seed,9),mode);int at=body,span=1;for(var a:row.anchors()){add(c,row.source().substring(at,a.start()),style(seed,0),mode);add(c,a.from(),style(seed,span++),mode);at=a.start()+a.from().length();}add(c,row.source().substring(at),style(seed,0),mode);add(c,suffix,style(seed,10),mode);return c;}
    private static void anchors(Row row,Component before,Component after,String prefix){var in=styles(before);var out=styles(after);for(var a:row.anchors()){var expected=in.get(prefix.length()+a.start());for(int n=prefix.length()+a.end();n<prefix.length()+a.end()+a.to().length();n++)check(out.get(n).equals(expected),"semantic color/actions "+row.speaker()+": "+a.to());}}
    private static String noun(int n){int end=n%100;return end>=11&&end<=14?"вредителей":n%10==1?"вредитель":n%10>=2&&n%10<=4?"вредителя":"вредителей";}
    private static void numbers(Component before,Component after){var a=java.util.regex.Pattern.compile("[0-9]+").matcher(plain(before));var b=java.util.regex.Pattern.compile("[0-9]+").matcher(plain(after));var x=styles(before);var y=styles(after);while(a.find()){check(b.find()&&a.group().equals(b.group()),"numeric text copied");check(x.subList(a.start(),a.end()).equals(y.subList(b.start(),b.end())),"each numeric glyph style/action copied");}check(!b.find(),"no invented values");}
    private static Component phillipFixture(String text,int seed){var spans=new ArrayList<int[]>();int pests=text.lastIndexOf("Pests");spans.add(new int[]{pests,pests+5,1});for(String term:List.of(" Farming Fortune","Vacuum Bag")){int at=text.indexOf(term);if(at>=0)spans.add(new int[]{at,at+term.length(),2});}
        var c=Component.empty();for(int i=0;i<text.length();i++){int span=0;for(var s:spans)if(i>=s[0]&&i<s[1])span=s[2];if(Character.isDigit(text.charAt(i)))span=20+i;add(c,text.substring(i,i+1),style(seed,span),0);}return c;}
    private static void phillip(Path root,OfflineDictionary db,JsonObject evidence)throws Exception{
        for(int n:new int[]{1,2,5,11,21,40,133,999999})for(int duration:new int[]{1,30})for(int bonus:new int[]{7,200})for(int seed=1;seed<=3;seed++)for(String suffix:List.of(""," (x17)"," (×2)"))for(boolean reward:List.of(true,false)){
            String head="[05:23:11] [NPC] Pesthunter Phillip: ",acc=n%100>=11&&n%100<=14||n%10!=1?"вредителей":"вредителя";
            String source=head+(reward?"In exchange for "+n+" Pests, I've given you +"+bonus+" Farming Fortune for "+duration+"m!":"You've exchanged enough Pests with me recently. You still have "+n+" Pests in your Vacuum Bag!")+suffix;
            String target=head+(reward?"В обмен на "+n+" "+acc+", я дал тебе +"+bonus+" фермерской удачи на "+duration+" мин!":"Ты недавно уже сдал достаточно вредителей. У тебя осталось "+n+" "+noun(n)+" в пылесборнике!")+suffix;
            var input=phillipFixture(source,seed);var output=queued(input);check(plain(output).equals(target),"Phillip complete numeric receipt: "+plain(output));numbers(input,output);check(plain(input).equals(source),"Phillip original immutable");check(queued(output)==output,"Phillip idempotence");for(var channel:List.of(GuiMessageSource.PLAYER,GuiMessageSource.SYSTEM_CLIENT)){var m=msg(input,channel);check(SkyRuClient.npcChat(m)==m,"Phillip channel");}flag("translateGameChat",false);check(plain(queued(input)).equals(target),"Phillip NPC-only switch");flag("translateGameChat",true);
            for(String term:reward?List.of(" фермерской удачи"):List.of("пылесборнике")){int at=plain(output).indexOf(term);for(int i=at;i<at+term.length();i++)check(styles(output).get(i).equals(style(seed,2)),"Phillip term style/action");}
        }
        int observed=0;for(var raw:evidence.getAsJsonArray("records")){var e=raw.getAsJsonObject();String source=e.get("source").getAsString();if(!source.startsWith("[NPC] Pesthunter Phillip: In exchange for ")&&!source.startsWith("[NPC] Pesthunter Phillip: You've exchanged enough Pests"))continue;var input=Component.literal(e.get("sample").getAsString());String target=source.contains("In exchange for")?"[NPC] Pesthunter Phillip: В обмен на 40 вредителей, я дал тебе +200 фермерской удачи на 30 мин!":"[NPC] Pesthunter Phillip: Ты недавно уже сдал достаточно вредителей. У тебя осталось 133 вредителя в пылесборнике!";var output=queued(input);check(plain(output).equals(target),"observed Phillip receipt, not generated colour layout");numbers(input,output);observed++;}check(observed==2,"two independent live-text receipts");
        String source="[NPC] Pesthunter Phillip: In exchange for 40 Pests, I've given you +200 Farming Fortune for 30m!";var c=Component.literal(source);
        for(String key:List.of(source,"Pests","Farming Fortune","Vacuum Bag")){var own=root.resolve("phillip-override-"+checks);Files.createDirectories(own);Files.writeString(own.resolve("overrides.tsv"),key+"\tМой текст\n");flag("dictionary",new OfflineDictionary(own));flag("chatNotifications",new ChatNotificationTranslator(new OfflineDictionary(own)));check(queued(c)==c,"Phillip override");}flag("dictionary",db);flag("chatNotifications",new ChatNotificationTranslator(db));
        for(String bad:List.of(source.replace("40","-40"),source.replace("200","2,000"),source.replace("30m","30h"),source.replace("Pesthunter Phillip","Unknown"),source+" EXTRA")){var x=Component.literal(bad);check(queued(x)==x,"unseen malformed receipt not guessed");}
    }
    public static void main(String[] args)throws Exception{
        var root=Path.of(args[0]);var sourceRoot=Path.of(args[1]);var db=new OfflineDictionary(root);db.setRecordUnknown(false);var npc=NpcDialogueTranslator.storyDialogues();
        flag("dictionary",db);flag("enabled",true);flag("onlyHypixel",false);flag("translateNpcChat",true);flag("translateGameChat",true);flag("storyDialogues",npc);flag("npcDialogues",new NpcDialogueTranslator());flag("chatNotifications",new ChatNotificationTranslator(db));
        var rows=new ArrayList<Row>();var expected=new HashMap<String,Row>();var seenSpeakers=new TreeSet<String>();
        for(String line:Files.readAllLines(sourceRoot.resolve("HUB_NPC_0.15.69_REVIEWED.tsv"))){if(line.isEmpty()||line.startsWith("#"))continue;var f=line.split("\\|",-1);String prefix="[NPC] "+f[0]+": ",source=prefix+f[1],target=prefix+f[2];var spans=new ArrayList<Anchor>();
            if(f.length==4)for(var raw:JsonParser.parseString(f[3]).getAsJsonArray()){var a=raw.getAsJsonObject();String from=a.get("source").getAsString(),to=a.get("target").getAsString();int i=nth(source,from,a.has("source_occurrence")?a.get("source_occurrence").getAsInt():0,prefix.length()),j=nth(target,to,a.has("target_occurrence")?a.get("target_occurrence").getAsInt():0,prefix.length());spans.add(new Anchor(from,to,i,j));}
            spans.sort(Comparator.comparingInt(Anchor::start));var row=new Row(f[0],source,target,List.copyOf(spans));rows.add(row);check(expected.put(source,row)==null,"unique reviewed source");seenSpeakers.add(f[0]);
        }
        check(rows.size()==83&&seenSpeakers.size()==20&&npc.phraseCount()==10799,"exact retained batch83 /20 speakers /581 base plus239 NPC74 and100 separately checked NPC75 additions plus137 NPC77 additions plus324 NPC78 additions");
        var resource=JsonParser.parseReader(new java.io.InputStreamReader(TestHubNpcs69.class.getResourceAsStream("/data/witherskyru/hub-dialogues.json"),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().getAsJsonArray("records");check(resource.size()==83,"packaged resource count");
        for(var raw:resource){var row=raw.getAsJsonObject();check(expected.containsKey(row.get("source").getAsString())&&expected.get(row.get("source").getAsString()).target().equals(row.get("translation").getAsString()),"reviewed resource, not self-generated expectation");}
        int rowIndex=0;for(var row:rows){for(int seed=1;seed<=3;seed++)for(int mode=0;mode<2;mode++)for(String prefix:List.of("","[05:23:11] "))for(String suffix:List.of(""," (x17)"," (×2)")){
            var input=fixture(row,prefix,suffix,seed,mode);var output=queued(input);check(plain(output).equals(prefix+row.target()+suffix),"dispatch "+row.source()+" => "+plain(output));anchors(row,input,output,prefix);check(plain(input).equals(prefix+row.source()+suffix),"original immutable");
            var before=styles(input);var after=styles(output);int plen=prefix.length()+row.source().indexOf(": ")+2;check(before.subList(0,plen).equals(after.subList(0,plen)),"speaker/time unchanged");if(!suffix.isEmpty())check(before.subList(before.size()-suffix.length(),before.size()).equals(after.subList(after.size()-suffix.length(),after.size())),"counter styles unchanged");
            for(int n=0;n<3;n++)check(npc.translate(output,db)==output,"idempotence");for(var channel:List.of(GuiMessageSource.PLAYER,GuiMessageSource.SYSTEM_CLIENT)){var protectedMsg=msg(input,channel);check(SkyRuClient.npcChat(protectedMsg)==protectedMsg,"whole player/client protection");}var signed=new GuiMessage(0,input,new MessageSignature(new byte[256]),GuiMessageSource.SYSTEM_SERVER,null);check(SkyRuClient.npcChat(signed)==signed,"signed protection");
            flag("translateNpcChat",false);check(queued(input)==input,"NPC switch");flag("translateNpcChat",true);flag("translateGameChat",false);check(plain(queued(input)).equals(prefix+row.target()+suffix),"NPC independent of notification switch");flag("translateGameChat",true);
        }
            var custom=root.resolve("override-"+(rowIndex++));Files.createDirectories(custom);Files.writeString(custom.resolve("overrides.tsv"),row.source()+"\tМой перевод\n");var own=new OfflineDictionary(custom);own.setRecordUnknown(false);var in=Component.literal(row.source());check(npc.translate(in,own)==in,"whole override veto");for(var anchor:row.anchors()){Files.writeString(custom.resolve("overrides.tsv"),anchor.from()+"\tМой термин\n");own=new OfflineDictionary(custom);check(npc.translate(in,own)==in,"semantic override veto");}
        }
        var evidence=JsonParser.parseString(Files.readString(sourceRoot.resolve("HUB_NPC_OBSERVED_0.15.69.json"))).getAsJsonObject();int observed=0;var observedSources=new HashSet<String>();
        for(var raw:evidence.getAsJsonArray("records")){var e=raw.getAsJsonObject();String source=e.get("source").getAsString(),base=source.replaceFirst(" \\((?:x|×)[0-9]+\\)$","");var row=expected.get(base);if(row==null)continue;String suffix=source.substring(base.length());var original=Component.literal(e.get("sample").getAsString());check(plain(original).equals(source),"independent sample normalization");var output=queued(original);check(plain(output).equals(row.target()+suffix),"OBSERVED rich color source: "+source+" => "+plain(output));anchors(row,original,output,"");observed++;observedSources.add(base);}
        check(observedSources.size()==53&&observed>=53,"all53 observed source bodies rendered, including repeats");
        phillip(root,db,evidence);
        String[][] choices={{"Ok, then what?","Хорошо, а дальше?"},{"Accessory Power?","Сила аксессуаров?"},{"Magical Power?","Магическая сила?"},{"That's amazing!","Потрясающе!"}};
        for(var p:choices)for(int seed=1;seed<=3;seed++){var c=Component.literal("[05:23:11] Select an option: [").setStyle(style(seed,0)).append(Component.literal(p[0]).setStyle(style(seed,1))).append(Component.literal("]").setStyle(style(seed,2)));var output=queued(c);check(plain(output).equals("[05:23:11] Выберите ответ: ["+p[1]+"]"),"option label");int at=plain(output).indexOf(p[1]);for(int i=at;i<at+p[1].length();i++)check(styles(output).get(i).equals(style(seed,1)),"option command/hover untouched");}
        for(var raw:evidence.getAsJsonArray("observed_choice_samples")){var e=raw.getAsJsonObject();String source=e.get("source").getAsString();String target=null;for(var r:evidence.getAsJsonArray("choices")){var x=r.getAsJsonObject();if(x.get("source").getAsString().equals(source))target=x.get("target").getAsString();}check(target!=null,"observed choice target");check(plain(queued(Component.literal(e.get("sample").getAsString()))).strip().equals(target),"observed choice legacy");}
        String[][] roles={{"Thaumaturgist","Тауматург"},{"Maths Enjoyer","Любитель математики"},{"Enchantment Nerd","Знаток зачарований"},{"ENCHANTMENT GUIDE","СПРАВОЧНИК ЗАЧАРОВАНИЙ"},{"CLICK","НАЖМИТЕ"}};
        for(var p:roles)for(int seed=1;seed<=3;seed++){var c=Component.literal(p[0]).setStyle(style(seed,1));var out=SkyRuClient.minionNameTag(c,false);check(plain(out).equals(p[1]),"closed world role "+p[0]);for(var s:styles(out))check(s.equals(style(seed,1)),"world style");check(SkyRuClient.minionNameTag(c,true)==c,"even matching player entity protected");check(SkyRuClient.minionNameTag(out,false)==out,"world idempotence");var legacy=Component.literal("§6"+p[0]);check(plain(SkyRuClient.minionNameTag(legacy,false)).equals(p[1]),"legacy world role");}
        check(db.translate("CLICK").equals("CLICK"),"world prompt must not become a global item substring");
        var fragmented=Component.literal("CL").setStyle(style(7,1)).append(Component.literal("ICK").setStyle(style(7,1)));check(plain(SkyRuClient.minionNameTag(fragmented,false)).equals("НАЖМИТЕ"),"uniform fragmented world prompt");
        var unsupported=Component.literal("CL").setStyle(style(7,1)).append(Component.literal("ICK").setStyle(style(7,2)));check(SkyRuClient.minionNameTag(unsupported,false)==unsupported,"unmapped mixed actions not flattened");
        var translatedKey=Component.translatable("CLICK");check(SkyRuClient.minionNameTag(translatedKey,false)==translatedKey,"nonliteral world prompt protected");
        var worldOwn=root.resolve("world-override");Files.createDirectories(worldOwn);Files.writeString(worldOwn.resolve("overrides.tsv"),"CLICK\tМоё действие\n");var worldDb=new OfflineDictionary(worldOwn);flag("dictionary",worldDb);check(plain(SkyRuClient.minionNameTag(Component.literal("CLICK"),false)).equals("Моё действие"),"world prompt override");flag("dictionary",db);
        for(String unknown:List.of("Maxwell","Wither_101","Blacksmith","Unknown role","[VIP] Maxwell: Accessories are X magical X pieces of gear.","[NPC] Maxwell: Entirely new unobserved speech.","Select an option: [That's amazing!] [Unknown choice]")){var c=Component.literal(unknown);check(SkyRuClient.minionNameTag(c,false)==c,"unknown label unchanged");check(queued(c)==c,"unknown/personal text unchanged");}
        flag("enabled",false);var role=Component.literal("Thaumaturgist");check(SkyRuClient.minionNameTag(role,false)==role,"disabled world hook");
        System.out.println("PASS: Hub NPC69 "+checks+" assertions;83 reviewed exact lines/20 speakers;53 observed source bodies;"+observed+" legacy variants;2 numeric Phillip receipts;4 choice labels;5 closed world labels;fresh styles/actions,PLAYER/client/signed guards,overrides,toggles,counters;not all NPCs or live FPS");
    }
}
